#include <stdio.h>
#include <stdlib.h>

#define FILE_PATH "/safe/example.txt"

int main() {
    FILE *file;
    char buffer[1024];

    // Open the file in read mode
    file = fopen(FILE_PATH, "r");
    if (file == NULL) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    // Read the contents of the file into a buffer
    while (fgets(buffer, sizeof(buffer), file) != NULL) {
        printf("%s", buffer);
    }

    // Close the file
    fclose(file);

    return EXIT_SUCCESS;
}
```

