@app.route('/')
def index():
    if 'logged_in' not in session:
        return redirect('/login')

    if session['user_type'] == 'admin':
        return redirect('/admin')

    return redirect('/user')

@app.route('/login', methods=['GET'])
def login():
    # login logic here
    session['logged_in'] = True
    session['user_type'] = 'admin'  # or 'user'
    return redirect('/')

@app.route('/user')
def user():
    if not session.get('logged_in') or session['user_type'] != 'user':
        return redirect('/')

    # display user page here
    return "Welcome, User!"

@app.route('/admin')
def admin():
    if not session.get('logged_in') or session['user_type'] != 'admin':
        return redirect('/')

    # display admin page here
    return "Welcome, Admin!"

if __name__ == '__main__':
    app.run(debug=True)
```

