    const char *filename = "important_config";

    // Define the mode and permissions
    int flags = O_CREAT | O_RDWR;
    mode_t perms = S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH;  // Read/write for owner and group, read-only for others

    // Open the file with the specified flags and permissions
    int fd = open(filename, flags, perms);

