#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define FILENAME "output.txt"

// Function to generate a random float between 0 and 1
float generateRandomFloat() {
    return (float)rand() / RAND_MAX;
}

// Function to convert a float to a string
char* floatToString(float value) {
    // Assuming the float will not be larger than 32 characters when converted to string
    char *str = (char *)malloc(32 * sizeof(char));
    if (str == NULL) {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    sprintf(str, "%f", value);
    return str;
}

// Function to concatenate two strings
char* concatenateStrings(const char *str1, const char *str2) {
    // Calculate the length of both strings
    size_t len1 = strlen(str1);
    size_t len2 = strlen(str2);

    // Allocate memory for the concatenated string
    char *result = (char *)malloc(len1 + len2 + 1); // +1 for the null terminator
    if (result == NULL) {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Copy the first string to the result
    strcpy(result, str1);

    // Append the second string to the result
    strcat(result, str2);

    return result;
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Generate three random floats
    float randomFloat1 = generateRandomFloat();
    float randomFloat2 = generateRandomFloat();
    float randomFloat3 = generateRandomFloat();

    // Convert the random floats to strings
    char *str1 = floatToString(randomFloat1);
    char *str2 = floatToString(randomFloat2);
    char *str3 = floatToString(randomFloat3);

    // Concatenate the strings
    char *resultStr = concatenateStrings(concatenateStrings(str1, str2), str3);

    // Write the concatenated string to a file
    FILE *file = fopen(FILENAME, "w");
    if (file == NULL) {
        printf("Failed to open file\n");
        exit(EXIT_FAILURE);
    }
    fprintf(file, "%s", resultStr);
    fclose(file);

    // Free allocated memory
    free(str1);
    free(str2);
    free(str3);
    free(resultStr);

    printf("Random floats written to %s\n", FILENAME);

    return 0;
}
```

### Explanation:
1. **Generating Random Floats**: The `generateRandomFloat` function generates a random float between 0 and 1.
