                 "    <title>Hello Page</title>\n"
                 "</head>\n"
                 "<body>\n"
                 "    <h1>Hello, %s!</h1>\n"
                 "</body>\n"
                 "</html>", username);
    } else {
        // If no username is provided, send a default message
        snprintf(outputbuf, sizeof(outputbuf),
                 "<!DOCTYPE html>\n"
                 "<html lang=\"en\">\n"
                 "<head>\n"
                 "    <meta charset=\"UTF-8\">\n"
                 "    <title>Hello Page</title>\n"
                 "</head>\n"
                 "<body>\n"
                 "    <h1>Hello, Guest!</h1>\n"
                 "</body>\n"
                 "</html>");
    }

    // Write the response body to the response stream
    fprintf(response_stream, "%s", outputbuf);

    // Close the response stream
    fclose(response_stream);
}

