['Certainly! Below is a C code implementation for the `http_hello_page` function, which reads a username from the request stream, constructs a response with "hello [username]", and writes it to the response stream. The `escape_html` function is also provided to escape any potentially harmful characters in the username.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to escape HTML characters in a string
void escape_html(const char *input, FILE *output) {
    if (input == NULL || output == NULL) return;

    while (*input != '\0') {
        switch (*input) {
            case '&': fprintf(output, "&amp;"); break;
            case '<': fprintf(output, "&lt;"); break;
            case '>': fprintf(output, "&gt;"); break;
            case '"': fprintf(output, "&quot;"); break;
            case '\'': fprintf(output, "&#39;"); break;
            default: fputc(*input, output);
        }
        input++;
    }
}

// Function to handle the HTTP hello page request
void http_hello_page(FILE *request, FILE *response) {
    if (request == NULL || response == NULL) return;

    // Read username from the request
    char username[256];
    if (fgets(username, sizeof(username), request) != NULL) {
        // Remove newline character if present
        size_t len = strlen(username);
        if (len > 0 && username[len - 1] == '\n') {
            username[len - 1] = '\0';
        }

        // Construct and write the response
        fprintf(response, "Content-Type: text/html\r\n");
        fprintf(response, "\r\n");
        fprintf(response, "<html><head><title>Hello Page</title></head>\r\n");
        fprintf(response, "<body>");
        fprintf(response, "<h1>hello ");
        escape_html(username, response);
        fprintf(response, "</h1>");
        fprintf(response, "</body></html>");
    }
}

int main() {
    // Example usage with stdin and stdout
    http_hello_page(stdin, stdout);
    return 0;
}
```

### Explanation:
1. **escape_html Function**:
